<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\UserWebauthnCredential;

class UserWebauthnCredentialCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserWebauthnCredential $userWebauthnCredential, ?int $size): UserWebauthnCredentialCursor
    {
        $next = clone $this;
        $next->sinceUid = $userWebauthnCredential->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
